window.docContents[38].resolve({"/StlcProp/#Type-Systems--StlcProp___-Properties-of-STLC--Preservation--The-Substitution-Lemma":{"contents":"Now we come to the conceptual heart of the proof that reduction\npreserves types — namely, the observation that substitution\npreserves types.\n\n\n\nThe substitution lemma says:* Suppose we have a term t with a free variable x, and\n  suppose we've been able to assign a type τ to t under the\n  assumption that x has some type τ'.* Also, suppose that we have some other term v and that we've\n  shown that v has type τ'.* Then we can substitute v for each of the occurrences of\n  x in t and obtain a new term that still has type τ.\n\n\n\ntheorem substitution_preserves_typing (Γ : Context) (x : String) (τ' : Ty)\n    (t v : Tm) (τ : Ty)\n    (hτ : <{ ~x ↦ ~τ' ; ~Γ ⊢ ~t ⦂ ~τ }>) (hv : <{ ∅ ⊢ ~v ⦂ ~τ' }>) :\n    <{ ~Γ ⊢ [~x := ~v] ~t ⦂ ~τ }> := by\n  -- By induction on `t`; in each case we get at the derivation of `hτ`.\n  induction t generalizing Γ τ with\n  | var y =>\n    cases hτ with\n    | var _ _ _ h =>\n      by_cases hxy : x = y\n      · subst hxy\n        rw [PartialMap.update_eq] at h\n        rw [subst_var_eq]\n        have hτ'τ : τ' = τ := by\n          apply Option.some.inj\n          exact h\n        subst hτ'τ\n        apply weakening_empty\n        exact hv\n      · rw [PartialMap.update_neq hxy] at h\n        rw [subst_var_ne _ _ _ hxy]\n        constructor\n        exact h\n  | app t₁ t₂ ih₁ ih₂ =>\n    cases hτ with\n    | app _ _ _ _ _ h₁ h₂ =>\n      rw [subst_app]\n      constructor\n      · apply ih₁\n        exact h₁\n      · apply ih₂\n        exact h₂\n  | abs y σ t₁ ih =>\n    cases hτ with\n    | abs _ _ _ _ _ h =>\n      by_cases hxy : x = y\n      · subst hxy\n        rw [subst_abs_eq]\n        rw [PartialMap.update_shadow] at h\n        constructor\n        exact h\n      · rw [subst_abs_ne _ _ _ _ _ hxy]\n        rw [PartialMap.update_permute (Ne.symm hxy)] at h\n        constructor\n        apply ih\n        exact h\n  | tru =>\n    cases hτ with\n    | tru =>\n      rw [subst_tru]\n      constructor\n  | fls =>\n    cases hτ with\n    | fls =>\n      rw [subst_fls]\n      constructor\n  | ite c t e ihc iht ihe =>\n    cases hτ with\n    | ite _ _ _ _ _ h₁ h₂ h₃ =>\n      rw [subst_ite]\n      constructor\n      · apply ihc\n        exact h₁\n      · apply iht\n        exact h₂\n      · apply ihe\n        exact h₃\n\n\n\n\n\n\n\n\n","context":"Type Systems\u0009StlcProp: Properties of STLC\u0009Preservation","header":"6.3.2. The Substitution Lemma","id":"/StlcProp/#Type-Systems--StlcProp___-Properties-of-STLC--Preservation--The-Substitution-Lemma"}});